  c = mix(c, crust, coralline);
  let turf = smoothstep(0.68, 0.84, globes_noise3(pb * 14.0 + vec3f(7.7)));
  c = mix(c, vec3f(0.24, 0.32, 0.13) * (0.8 + 0.4 * n3), turf * 0.7);
  let pit = smoothstep(0.78, 0.88, globes_noise3(pb * 140.0 + vec3f(1.9)));
  c *= 1.0 - 0.4 * pit;
