  let black = row + vec3i(2 * i32(lid.x) + ((s + 1) & 1), 0, 0);
  if (all(black < vec3i(n))) { psiOut[pressureIdx(black.x, black.y, black.z)] = relax(black, boxIdx(black - o), n); }
